// Utility used only to type TRANSLATIONS below — new sections/keys were
// added to the interface for vi/en/zh's real content, but the other 11
// languages weren't touched (still have their pre-existing keys only).
// DeepPartial lets those older, now-incomplete language objects keep
// type-checking as-is; getTranslation() below deep-merges them onto the
// (fully-populated) `en` object at read time so every key always resolves
// to *something* — real content where translated, English otherwise.
type DeepPartial<T> = T extends readonly unknown[]
  ? T
  : T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

