function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Recursive merge, override wins whenever it defines a key; arrays are
// replaced wholesale (a translated feature list fully replaces English's,
// never merged item-by-item).
function deepMerge<T>(base: T, override: DeepPartial<T> | undefined): T {
  if (!override) return base;
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return (override as T) ?? base;
  }
  const result: Record<string, unknown> = { ...base };
  const overrideObj = override as Record<string, unknown>;
  for (const key of Object.keys(overrideObj)) {
    const overrideVal = overrideObj[key];
    const baseVal = (base as Record<string, unknown>)[key];
    result[key] =
      isPlainObject(overrideVal) && isPlainObject(baseVal)
        ? deepMerge(baseVal, overrideVal as DeepPartial<typeof baseVal>)
        : overrideVal !== undefined
        ? overrideVal
        : baseVal;
  }
  return result as T;
}

// `en` must stay fully populated — it's the runtime fallback base every
// other language merges onto, not just the English translation.
export function getTranslation(lang: SupportedLanguage = "vi"): TranslationDictionary {
  const base = TRANSLATIONS.en as unknown as TranslationDictionary;
  if (lang === "en") return base;
  return deepMerge<TranslationDictionary>(base, TRANSLATIONS[lang]);
}
